package com.inventra.backend.model; public class OrderItem { private String productId; private int quantity; private double unitPrice; public OrderItem(){} public OrderItem(String p,int q,double u){productId=p;quantity=q;unitPrice=u;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public double getUnitPrice(){return unitPrice;} public void setUnitPrice(double v){unitPrice=v;} public double getLineTotal(){return unitPrice*quantity;} }
